  --teal: #176b62;
  --orange: #d96a34;
  --gold: #b8882a;
  --red: #c5483d;
  --shadow: 0 24px 60px rgba(20, 33, 31, 0.12);
  --radius-lg: 28px;
  --radius-md: 18px;
  --radius-sm: 12px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  height: 100vh; /* 鎖定視窗高度 */
  display: flex;
  flex-direction: column;
  font-family: "IBM Plex Sans", "Noto Sans TC", sans-serif;
  color: var(--ink);
  background: #f3efe7;
  overflow: hidden; /* 禁用全體捲動 */
}

.shell {
  flex: 1;
  width: 100%;
  max-width: 100vw;
  margin: 0;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow: hidden;
  box-sizing: border-box;
}

.hero {
  padding: 12px 24px;
  border-radius: var(--radius-md);
  flex-shrink: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--paper);
  border: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-size: 0.78rem;
  color: var(--teal);
}

h1,
h2,
h3,
p {
  margin: 0;
}

h1 {
  font-family: inherit;
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0;
}

.hero-copy,
.section-copy,
.meta-label,
.meta-copy,
.lane-copy,
.task-summary,
.card-copy,
.chip,
.snapshot-item,
.status-pill,
.activity-meta {
  color: var(--muted);
}

.hero-actions {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  min-width: auto;
}

.primary-button {
  border: 0;
  border-radius: 999px;
  background: var(--ink);
  color: #fffdf7;
  padding: 12px 18px;
  font-size: 0.95rem;
  cursor: pointer;
  transition: transform 160ms ease, opacity 160ms ease;
}

.primary-button:hover {
  transform: translateY(-1px);
  opacity: 0.92;
}

.meta-card,
.panel,
.lane,
.task-card,
.stack-card,
.snapshot-card,
.activity-card,
.workload-card {
  border: 1px solid var(--line);
  background: var(--paper);
  backdrop-filter: blur(10px);
}

.workload-bar {
  height: 10px;
  border-radius: 999px;
  background: rgba(20, 33, 31, 0.08);
  overflow: hidden;
  margin: 14px 0 10px;
}

.workload-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--teal), var(--orange));
}

.lane-head,
.task-head,
.stack-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.status-pill {
  border-radius: 999px;
  padding: 5px 10px;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  background: rgba(20, 33, 31, 0.08);
}

.status-working,
.status-in_progress {
  color: var(--teal);
  background: rgba(23, 107, 98, 0.12);
}

.status-ready {
  color: var(--teal);
  background: rgba(23, 107, 98, 0.12);
}

.status-reviewing,
.status-review {
  color: var(--gold);
  background: rgba(184, 136, 42, 0.12);
}

.status-waiting {
  color: var(--orange);
  background: rgba(217, 106, 52, 0.12);
}

.status-blocked {
  color: var(--red);
  background: rgba(197, 72, 61, 0.12);
}

.status-done {
  color: var(--muted);
  background: rgba(88, 104, 102, 0.12);
}

.main-grid {
  flex: 1;
  display: grid;
  grid-template-columns: 320px 1fr 380px; /* 系統狀態, 任務板, 活動紀錄 */
  gap: 16px;
  overflow: hidden;
}

.pane {
  display: flex;
  flex-direction: column;
  background: var(--paper);
  border-radius: var(--radius-md);
  border: 1px solid var(--line);
  overflow: hidden;
}

.pane-header {
  padding: 12px 16px;
  background: rgba(20, 33, 31, 0.04);
  border-bottom: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.pane-content {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.delivery-layer {
  border-radius: var(--radius-md);
  background: rgba(20, 33, 31, 0.04);
  border: 1px solid rgba(20, 33, 31, 0.08);
  padding: 16px;
}

.delivery-layer-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
  margin-bottom: 12px;
}

.delivery-layer-head h3 {
  margin-bottom: 6px;
  font-size: 1rem;
}

.delivery-layer-grid {
  display: grid;
  gap: 12px;
}

.dependency-schedule {
  display: grid;
  gap: 14px;
  margin-top: 16px;
}

#audit-summary {
  margin-bottom: 16px;
}

.dependency-wave {
  border-radius: var(--radius-md);
  background: rgba(20, 33, 31, 0.04);
  border: 1px solid rgba(20, 33, 31, 0.08);
  padding: 16px;
}

.dependency-wave-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: baseline;
  margin-bottom: 12px;
}

.dependency-wave-head h3 {
  font-size: 1rem;
}

.dependency-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.dependency-card {
  border-radius: var(--radius-md);
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.72);
  padding: 16px;
}

.dependency-card.ready-now {
  border-color: rgba(23, 107, 98, 0.24);
  background: rgba(23, 107, 98, 0.08);
}

.dependency-card.blocked-now {
  border-color: rgba(197, 72, 61, 0.18);
}

.dependency-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.dependency-copy {
  margin-top: 10px;
  color: var(--muted);
}

.board-column {
  padding: 0;
  background: none;
  border: none;
}

.board-column h3 {
  margin: 16px 0 12px;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.column-stack,
.stack,
.snapshot,
.activity {
  display: grid;
  gap: 12px;
}

.task-card,
.delivery-card,
.stack-card,
.snapshot-card,
.activity-card {
  background: rgba(255, 255, 255, 0.62);
}

.task-meta,
.task-foot,
.lane-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.chip {
  display: inline-flex;
  align-items: center;
  padding: 4px 9px;
  border-radius: 999px;
  background: rgba(20, 33, 31, 0.07);
  font-size: 0.8rem;
}

.empty {
  color: var(--muted);
  font-style: italic;
}

.activity-card {
  display: grid;
  gap: 6px;
}

.activity-message {
  font-size: 0.95rem;
}

.task-summary {
  margin-top: 10px;
  line-height: 1.55;
}

.review-block {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px dashed rgba(20, 33, 31, 0.14);
}

.review-title {
  font-size: 0.82rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--orange);
}

.note-list {
  margin: 8px 0 0;
  padding-left: 18px;
  display: grid;
  gap: 6px;
  color: var(--muted);
}

.note-list.compact {
  margin-top: 10px;
}

code {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.85em;
  background: rgba(20, 33, 31, 0.06);
  padding: 1px 5px;
  border-radius: 6px;
}

/* ── Progress bar ── */
.progress-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 14px;
}
.progress-label {
  font-size: 0.85rem;
  color: var(--muted);
  white-space: nowrap;
}
.progress-track {
  flex: 1;
  height: 8px;
  background: var(--line);
  border-radius: 99px;
  overflow: hidden;
  max-width: 320px;
}
.progress-fill {
  height: 100%;
  background: var(--teal);
  border-radius: 99px;
  transition: width 0.4s ease;
}

/* ── System Status ── */
.system-status-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}
.sys-card {
  background: rgba(255,255,255,0.5);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 14px 16px;
}
.sys-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  font-size: 0.95rem;
}
.sys-icon { font-size: 1.1rem; }
.sys-card-body {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 0.82rem;
}
.approval-item {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--line);
  width: 100%;
}

/* ── Worker history table ── */
.worker-history { overflow-x: auto; }
.worker-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}
.worker-table th {
  text-align: left;
  padding: 6px 10px;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
  font-weight: 600;
}
.worker-table td {
  padding: 7px 10px;
  border-bottom: 1px solid var(--line);
}
.worker-row.worker-completed td:first-child { color: #2a7a4f; }
.worker-row.worker-failed td:first-child { color: var(--red); }
.worker-row.worker-running td:first-child,
.worker-row.worker-started td:first-child { color: var(--gold); }
.worker-row.worker-manual_pending td:first-child { color: var(--muted); }

@media (max-width: 1100px) {
  .span-3,
  .span-6 {
    grid-column: span 6;
  }

  .workload-grid,
  .agent-lanes,
  .dependency-summary,
  .delivery-layers,
  .board {
    grid-template-columns: 1fr;
  }

  .dependency-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .shell {
    width: min(100vw - 20px, 100%);
    margin: 12px auto 24px;
  }

  .hero {
    flex-direction: column;
    padding: 20px;
  }

  .hero-actions {
    width: 100%;
    align-items: stretch;
    min-width: 0;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .span-3,
  .span-6 {
    grid-column: span 1;
  }
}

