.task-card,
.delivery-card,
.stack-card,
.snapshot-card,
.activity-card {
  background: rgba(255, 255, 255, 0.62);
}

.task-meta,
.task-foot,
.lane-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
