  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 0.82rem;
}
.approval-item {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
  padding-top: 6px;
