  const statusEl = qs("#system-status");
  const historyEl = qs("#worker-history");
  statusEl.innerHTML = "";
  historyEl.innerHTML = "";

  // Supervisor card
  const lastScan = orchState?.last_scan_at;
  const supervisorCard = document.createElement("article");
  supervisorCard.className = "sys-card";
  supervisorCard.innerHTML = `
    <div class="sys-card-head"><span class="sys-icon">🖥</span><strong>Supervisor</strong></div>
    <div class="sys-card-body">
      <span class="status-pill ${lastScan ? 'status-working' : 'status-blocked'}">${lastScan ? '有資料' : '無資料'}</span>
      <span class="chip">初始化：${formatTime(orchState?.initialized_at)}</span>
      <span class="chip">上次掃描：${timeAgo(lastScan)}</span>
    </div>
  `;
  statusEl.appendChild(supervisorCard);

  // Pending approvals card
  const pending = (approvalQueue?.pending || []).length;
  const approvalCard = document.createElement("article");
  approvalCard.className = "sys-card";
  approvalCard.innerHTML = `
    <div class="sys-card-head"><span class="sys-icon">⏳</span><strong>待批准佇列</strong></div>
    <div class="sys-card-body">
      <span class="status-pill ${pending > 0 ? 'status-review' : 'status-done'}">${pending > 0 ? `${pending} 個待處理` : '清空'}</span>
      ${(approvalQueue?.pending || []).map(a => `
        <div class="approval-item">
          <span class="chip">${a.provider}</span>
          <span class="chip">task=${a.task_id || '-'}</span>
          <span class="chip">${a.tool_name}</span>
          <span class="chip">${timeAgo(a.created_at)}</span>
        </div>
      `).join("")}
    </div>
  `;
  statusEl.appendChild(approvalCard);

  // Worker summary cards by provider
  const workers = Object.values(orchState?.workers || {});
  const providers = ["claude", "gemini", "codex", "copilot"];
  for (const provider of providers) {
    const pw = workers.filter(w => w.provider === provider);
    const running = pw.filter(w => ["running", "started"].includes(w.status)).length;
    const failed = pw.filter(w => w.status === "failed").length;

    const completed = pw.filter(w => w.status === "completed").length;
    const card = document.createElement("article");
    card.className = "sys-card";
    card.innerHTML = `
      <div class="sys-card-head"><span class="sys-icon">${running > 0 ? "🟡" : failed > 0 ? "🔴" : "⚪"}</span><strong>${provider}</strong></div>
      <div class="sys-card-body">
        <span class="chip">執行中 ${running}</span>
        <span class="chip">失敗 ${failed}</span>
        <span class="chip">完成 ${completed}</span>
      </div>
    `;
    statusEl.appendChild(card);
  }

  // Worker history table
  const recentWorkers = workers
    .sort((a, b) => (b.last_event_at || "").localeCompare(a.last_event_at || ""))
    .slice(0, 12);

  if (!recentWorkers.length) {
    historyEl.innerHTML = '<p class="empty">尚無 Worker 記錄。</p>';
    return;
  }

  const table = document.createElement("table");
  table.className = "worker-table";
  table.innerHTML = `
    <thead><tr>
      <th>狀態</th><th>Task</th><th>模式</th><th>Provider</th><th>最後活動</th>
    </tr></thead>
    <tbody>
      ${recentWorkers.map(w => `
        <tr class="worker-row worker-${w.status}">
          <td>${workerStatusIcon[w.status] || "?"} ${w.status}</td>
          <td><strong>${w.task_id || "-"}</strong></td>
          <td><code>${w.mode || "-"}</code></td>
          <td>${w.provider || w.agent_id || "-"}</td>
          <td>${timeAgo(w.last_event_at)}</td>
        </tr>
      `).join("")}
    </tbody>
  `;
  historyEl.appendChild(table);
}

function renderProgressBar(tasks) {
  const total = (tasks || []).length;
  const done = (tasks || []).filter(t => t.status === "done").length;
  const pct = total ? Math.round((done / total) * 100) : 0;
  const label = qs("#progress-label");
  const fill = qs("#progress-fill");
  if (label) label.textContent = `Sprint 進度：${done} / ${total} 完成 (${pct}%)`;
  if (fill) fill.style.width = `${pct}%`;
}

function renderActivity(entries) {
  const container = qs("#activity-list");
  container.innerHTML = "";
  const recent = entries.slice(-20).reverse();

  if (!recent.length) {
    const empty = document.createElement("p");
