        <p>等待對象：${blocker.waiting_for}</p>
        <p class="card-copy">${blocker.message}</p>
      `
    );
    renderSnapshot(snapshot);
    renderActivity(logs);
  } catch (error) {
    qs("#objective").textContent = `協作資料載入失敗：${error.message}`;
  }
}

qs("#refresh-button").addEventListener("click", () => {
  render();
});

render();

