  }

  // Worker history table
  const recentWorkers = workers
    .sort((a, b) => (b.last_event_at || "").localeCompare(a.last_event_at || ""))
    .slice(0, 12);

  if (!recentWorkers.length) {
    historyEl.innerHTML = '<p class="empty">尚無 Worker 記錄。</p>';
    return;
  }

  const table = document.createElement("table");
  table.className = "worker-table";
  table.innerHTML = `
    <thead><tr>
      <th>狀態</th><th>Task</th><th>模式</th><th>Provider</th><th>最後活動</th>
    </tr></thead>
    <tbody>
      ${recentWorkers.map(w => `
        <tr class="worker-row worker-${w.status}">
          <td>${workerStatusIcon[w.status] || "?"} ${w.status}</td>
          <td><strong>${w.task_id || "-"}</strong></td>
          <td><code>${w.mode || "-"}</code></td>
          <td>${w.provider || w.agent_id || "-"}</td>
          <td>${timeAgo(w.last_event_at)}</td>
        </tr>
      `).join("")}
    </tbody>
  `;
  historyEl.appendChild(table);
}

