const DATA_FILES = {
  status: "./ai-status.json",
  activity: "./ai-activity-log.jsonl",
  currentWork: "./current-work.md",
  orchestratorState: "../.orchestrator/state.json",
  approvalQueue: "../.orchestrator/approval-queue.json",
};

const boardColumns = [
  { key: "todo", label: "待開始" },
  { key: "in_progress", label: "進行中" },
  { key: "review", label: "待審查" },
  { key: "blocked", label: "已阻塞" },
  { key: "done", label: "已完成" },
];

const qs = (selector) => document.querySelector(selector);
const statusLabelMap = {
  idle: "待命",
  working: "工作中",
  reviewing: "審查中",
  ready: "可開工",
  waiting: "等前置",
  todo: "待開始",
