        metadata["approved_at"] = "2026-04-06T12:05:00Z"
        metadata["approver"] = "risk-committee"
        metadata["rollback"] = {
            "target_registry_id": "reg-strat-001-1.2.2",
            "target_version": "1.2.2",
        }
