async function fetchJson(path) {
  const response = await fetch(`${path}?t=${Date.now()}`, { cache: "no-store" });
  if (!response.ok) {
    throw new Error(`無法載入 ${path}: ${response.status}`);
  }
  return response.json();
}

async function fetchText(path) {
