    "deployment_stage",
    "plan_id",
    "persona_capital_binding_id",
    "target",
    "metrics"
  ],
  "properties": {
    "event_id": {
      "type": "string",
      "format": "uuid",
      "description": "Unique event identifier. Primary idempotency key for telemetry ingestion."
    },
    "event_type": {
      "type": "string",
      "enum": [
        "pnl_snapshot",
        "drawdown_snapshot",
        "slippage_observation",
        "fill_observation",
        "order_rejection",
        "deploy_started",
        "deploy_completed",
        "rollback_started",
        "rollback_completed",
        "pause_triggered",
        "liquidate_triggered",
        "governance_decision",
        "approval_action",
        "manual_override",
        "kill_switch_action",
        "heartbeat",
        "telemetry_mirror_mismatch"
      ],
      "description": "Canonical telemetry event type. Order/fill/deploy/rollback/governance events MUST NOT be sampled."
    },
    "created_at": {
      "type": "string",
      "format": "date-time",
      "description": "RFC3339 timestamp when this event was generated by the runtime. Must be >= binding effective_at and < binding retired_at (if retired)."
    },
    "execution_mode": {
      "type": "string",
      "enum": ["paper", "live"],
      "description": "Legacy execution mode field. For new events, this is a derived alias of deployment_stage (paper=paper, live=canary|live). Maintained for backward compatibility with legacy telemetry consumers."
    },
    "trace_id": {
      "type": "string",
      "format": "uuid",
      "description": "Distributed tracing correlation ID. Injected by telemetry-ingest-svc if not provided by the producer."
    },
    "environment": {
      "type": "string",
      "enum": ["paper", "canary", "live", "frozen"],
      "description": "Legacy environment field. For v1+ events, MUST equal deployment_stage. Documented as a derived alias pending deprecation."
    },

    "binding_id": {
      "type": "string",
      "format": "uuid",
      "description": "RuntimeBinding.binding_id — identifies the exact binding that produced this event. Primary join key to RuntimeBindingStore. (Evidence E-1)"
    },
    "runtime_id": {
      "type": "string",
      "description": "RuntimeBinding.runtime_id — the LEAN instance / container / worker that generated this event. (Evidence E-1)"
    },
    "capital_pool_id": {
      "type": "string",
      "description": "RuntimeBinding.capital_pool_id — the capital pool this event belongs to. Used for pool-scoped queries and lineage joins. (Evidence E-1)"
    },
    "artifact_id": {
      "type": "string",
      "description": "RuntimeBinding.artifact_id — the strategy/model artifact loaded. Required for performance attribution. (Evidence E-1)"
    },
    "artifact_version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "RuntimeBinding.artifact_version — semver version of the artifact. (Evidence E-1)"
    },
    "deployment_stage": {
      "type": "string",
      "enum": ["paper", "canary", "live", "frozen"],
      "description": "RuntimeBinding.deployment_mode mapped 1:1 into the telemetry envelope. Canonical deployment stage for this event. MUST match the deployment_mode of the binding referenced by binding_id. (Evidence E-2)"
    },
    "plan_id": {
      "type": "string",
      "description": "RuntimeBinding.plan_id — the DeploymentPlan that triggered this binding. Proves governance admissibility. (Evidence E-3)"
    },
    "persona_capital_binding_id": {
      "type": "string",
      "description": "RuntimeBinding.persona_capital_binding_id — links the event back through the binding to the persona registry. (Evidence E-3)"
    },
    "rollback_parent": {
      "type": "string",
      "format": "uuid",
      "description": "RuntimeBinding.rollback_parent — if this event was produced during a rollback, references the binding_id that was replaced. If set, rollback_action_type MUST also be set. (Evidence E-5)"
    },
    "rollback_action_type": {
      "type": "string",
      "enum": ["replace", "pause_then_replace", "liquidate_then_replace"],
      "description": "RuntimeBinding.rollback_action_type — the rollback strategy used. If set, rollback_parent MUST also be set. (Evidence E-5)"
    },

    "broker": {
      "type": "string",
      "description": "Broker / exchange name (optional, for trading events)."
    },
    "account_ref": {
      "type": "string",
      "description": "Account reference (optional, for trading events)."
    },
    "signal_id": {
      "type": "string",
      "description": "Associated signal ID (optional, for signal-driven events)."
    },
    "run_id": {
      "type": "string",
      "description": "Run / execution ID (optional, for experiment runs)."
    },

    "target": {
      "type": "object",
      "required": ["strategy_id"],
      "properties": {
        "registry_id": {
          "type": "string",
          "description": "Registry identifier for the strategy/model."
        },
        "strategy_id": {
          "type": "string",
          "description": "ID of the strategy this telemetry event relates to."
        },
        "artifact_version": {
          "type": "string",
          "description": "Artifact version (duplicate of top-level for legacy consumers)."
        },
        "artifact_type": {
          "type": "string",
          "enum": [
