          "type": "string",
          "enum": ["candidate", "paper", "live", "retired"]
        },
        "lineage_ref": {
          "type": "string",
          "description": "Optional lineage reference for cross-domain tracing."
        }
      },
      "additionalProperties": false
    },
    "metrics": {
      "type": "object",
      "minProperties": 1,
      "properties": {
        "pnl": { "type": "number" },
