        "slippage_bps": { "type": "number" },
        "fill_quantity": { "type": "number" },
        "fill_price": { "type": "number" },
        "reject_reason": { "type": "string" },
        "action": {
          "type": "string",
          "description": "Lifecycle action tag for non-metric events (deploy, rollback, kill-switch). Allows the event to pass minProperties=1 without inventing numeric telemetry."
        },
        "heartbeat": {
          "type": "integer",
          "description": "Heartbeat pulse indicator for non-metric keepalive events. Value is always 1."
        }
      },
      "additionalProperties": true,
      "description": "Event-specific metrics. additionalProperties allowed to support diverse event types."
    },
    "metadata": {
      "type": "object",
      "description": "Optional additional metadata. Not part of the evidence contract.",
      "additionalProperties": true
    }
  },
  "additionalProperties": false,

  "allOf": [
